public static int maxDiv(int[] arr, int low, int high) {
    if (low == high) return arr[low];
    int mid = (low + high) / 2;
    int leftMax = maxDiv(arr, low, mid);
    int rightMax = maxDiv(arr, mid + 1, high);
    return Math.max(leftMax, rightMax);
}
```
